import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import * as React from "react";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-cb-md text-sm font-medium ring-offset-cb-background transition-colors focus-visible:outline-none ring-inset disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0 transition-all duration-100 ease-in-out focus-visible:ring-2 focus-visible:ring-transparent focus:ring-1 focus-visible:ring-1 focus:ring-offset-2 focus-visible:ring-offset-2 dark:focus:ring-offset-1 dark:focus-visible:ring-offset-1 focus:ring-cb-background focus-visible:ring-cb-background focus:ring-offset-cb-ring focus-visible:ring-offset-cb-ring",
  {
    variants: {
      variant: {
        default:
          "bg-cb-primary text-cb-primary-foreground hover:bg-cb-primary/90",
        destructive:
          "bg-cb-destructive text-cb-destructive-foreground hover:bg-cb-destructive/90",
        outline:
          "border border-cb-border hover:bg-cb-accent hover:text-cb-accent-foreground [&_svg]:hover:text-cb-accent-foreground",
        secondary:
          "border border-cb-border bg-cb-secondary text-cb-secondary-foreground hover:bg-cb-secondary/80",
        ghost: "hover:bg-cb-accent hover:text-cb-accent-foreground",
        link: "text-cb-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-10 px-4 py-2",
        sm: "h-9 rounded-cb-md px-3",
        lg: "h-11 rounded-cb-md px-8",
        icon: "h-10 w-10",
        "icon-sm": "h-9 w-9",
        "icon-lg": "h-11 w-11",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button";
    return (
      <Comp
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        {...props}
      />
    );
  }
);
Button.displayName = "Button";

export { Button, buttonVariants };

"use client";

import * as SelectPrimitive from "@radix-ui/react-select";
import { Check, ChevronDown, ChevronUp } from "lucide-react";
import * as React from "react";

import { cn } from "@/lib/utils";

const Select = SelectPrimitive.Root;

const SelectGroup = SelectPrimitive.Group;

const SelectValue = SelectPrimitive.Value;

const SelectTrigger = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Trigger>
>(({ className, children, ...props }, ref) => (
  <SelectPrimitive.Trigger
    ref={ref}
    className={cn(
      "flex h-10 w-full items-center justify-between rounded-cb-md border border-transparent border-b-cb-foreground/40 bg-cb-input/20 px-3 py-2 text-sm ring-offset-cb-background placeholder:text-cb-muted-foreground focus:outline-none focus-visible:border-cb-primary focus-visible:ring-1 focus-visible:ring-cb-ring disabled:cursor-not-allowed disabled:opacity-50 [&>span]:line-clamp-1",
      className
    )}
    {...props}
  >
    {children}
    <SelectPrimitive.Icon asChild>
      <ChevronDown className="h-4 w-4 opacity-70" />
    </SelectPrimitive.Icon>
  </SelectPrimitive.Trigger>
));
SelectTrigger.displayName = SelectPrimitive.Trigger.displayName;

const SelectScrollUpButton = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.ScrollUpButton>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.ScrollUpButton>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.ScrollUpButton
    ref={ref}
    className={cn(
      "flex cursor-default items-center justify-center py-1 text-cb-foreground/70",
      className
    )}
    {...props}
  >
    <ChevronUp className="h-4 w-4" />
  </SelectPrimitive.ScrollUpButton>
));
SelectScrollUpButton.displayName = SelectPrimitive.ScrollUpButton.displayName;

const SelectScrollDownButton = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.ScrollDownButton>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.ScrollDownButton>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.ScrollDownButton
    ref={ref}
    className={cn(
      "flex cursor-default items-center justify-center py-1 text-cb-foreground/70",
      className
    )}
    {...props}
  >
    <ChevronDown className="h-4 w-4" />
  </SelectPrimitive.ScrollDownButton>
));
SelectScrollDownButton.displayName =
  SelectPrimitive.ScrollDownButton.displayName;

const SelectContent = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Content>
>(({ className, children, position = "popper", ...props }, ref) => (
  <SelectPrimitive.Portal>
    <SelectPrimitive.Content
      ref={ref}
      className={cn(
        "relative z-50 max-h-96 min-w-[8rem] overflow-hidden border bg-cb-popover text-cb-popover-foreground shadow-md data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2",
        position === "popper" &&
          "data-[side=bottom]:translate-y-1 data-[side=left]:-translate-x-1 data-[side=right]:translate-x-1 data-[side=top]:-translate-y-1",
        className
      )}
      position={position}
      {...props}
    >
      <SelectScrollUpButton />
      <SelectPrimitive.Viewport
        className={cn(
          "",
          position === "popper" &&
            "h-[var(--radix-select-trigger-height)] w-full min-w-[var(--radix-select-trigger-width)]"
        )}
      >
        {children}
      </SelectPrimitive.Viewport>
      <SelectScrollDownButton />
    </SelectPrimitive.Content>
  </SelectPrimitive.Portal>
));
SelectContent.displayName = SelectPrimitive.Content.displayName;

const SelectLabel = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Label>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Label>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.Label
    ref={ref}
    className={cn("py-1.5 pl-8 pr-2 text-sm font-semibold", className)}
    {...props}
  />
));
SelectLabel.displayName = SelectPrimitive.Label.displayName;

const SelectItem = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Item>
>(({ className, children, ...props }, ref) => (
  <SelectPrimitive.Item
    ref={ref}
    className={cn(
      "relative flex w-full cursor-default select-none items-center rounded-cb-md py-2 pl-8 pr-2 text-sm outline-none focus:bg-cb-accent focus:text-cb-accent-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
      className
    )}
    {...props}
  >
    <span className="absolute left-2 flex h-3.5 w-3.5 items-center justify-center text-cb-foreground/70">
      <SelectPrimitive.ItemIndicator>
        <Check className="h-4 w-4" />
      </SelectPrimitive.ItemIndicator>
    </span>

    <SelectPrimitive.ItemText>{children}</SelectPrimitive.ItemText>
  </SelectPrimitive.Item>
));
SelectItem.displayName = SelectPrimitive.Item.displayName;

const SelectSeparator = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Separator>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Separator>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.Separator
    ref={ref}
    className={cn("-mx-1 my-1 h-px bg-cb-muted", className)}
    {...props}
  />
));
SelectSeparator.displayName = SelectPrimitive.Separator.displayName;

export {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectScrollDownButton,
  SelectScrollUpButton,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
};

import { cva,type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

type FontSize =
  | "xs"
  | "sm"
  | "base"
  | "md"
  | "lg"
  | "xl"
  | "2xl"
  | "3xl"
  | "4xl"
  | "5xl"
  | "6xl"
  | "7xl";

type FontWeight = "normal" | "medium" | "semibold" | "bold" | "extrabold";

// extend type of props to include html attributes for the element
interface TypographyProps
  extends React.HTMLAttributes<HTMLElement>,
    VariantProps<typeof typographyVariants> {
  as?: React.ElementType;
  variant?: `${FontSize}/${FontWeight}`;
}

const typographyVariants = cva("font-normal  text-foreground", {
  variants: {
    variant: {
      // xs
      "xs/normal": "text-xs font-normal",
      "xs/medium": "text-xs font-medium",
      "xs/semibold": "text-xs font-semibold",
      "xs/bold": "text-xs font-bold",
      "xs/extrabold": "text-xs font-extrabold",

      // sm
      "sm/normal": "text-xs font-normal sm:text-sm",
      "sm/medium": "text-xs font-medium sm:text-sm",
      "sm/semibold": "text-xs font-semibold sm:text-sm",
      "sm/bold": "text-xs font-bold sm:text-sm",
      "sm/extrabold": "text-xs font-extrabold sm:text-sm",

      // base
      "base/normal": "text-sm font-normal sm:text-md",
      "base/medium": "text-sm font-medium sm:text-md",
      "base/semibold": "text-sm font-semibold sm:text-md",
      "base/bold": "text-sm font-bold sm:text-md",
      "base/extrabold": "text-sm font-extrabold sm:text-md",

      // md
      "md/normal": "text-sm font-normal md:text-md",
      "md/medium": "text-sm font-medium md:text-md",
      "md/semibold": "text-sm font-semibold md:text-md",
      "md/bold": "text-sm font-bold md:text-md",
      "md/extrabold": "text-sm font-extrabold md:text-md",

      // lg
      "lg/normal": "text-md font-normal md:text-lg",
      "lg/medium": "text-md font-medium md:text-lg",
      "lg/semibold": "text-md font-semibold md:text-lg",
      "lg/bold": "text-md font-bold md:text-lg",
      "lg/extrabold": "text-md font-extrabold md:text-lg",

      // xl
      "xl/normal": "text-lg font-normal md:text-xl",
      "xl/medium": "text-lg font-medium md:text-xl",
      "xl/semibold": "text-lg font-semibold md:text-xl",
      "xl/bold": "text-lg font-bold md:text-xl",
      "xl/extrabold": "text-lg font-extrabold md:text-xl",

      // 2xl
      "2xl/normal": "text-lg font-normal sm:text-xl md:text-2xl",
      "2xl/medium": "text-lg font-medium sm:text-xl md:text-2xl",
      "2xl/semibold": "text-lg font-semibold sm:text-xl md:text-2xl",
      "2xl/bold": "text-lg font-bold sm:text-xl md:text-2xl",
      "2xl/extrabold": "text-lg font-extrabold sm:text-xl md:text-2xl",

      // 3xl
      "3xl/normal": "text-xl font-normal sm:text-2xl md:text-3xl",
      "3xl/medium": "text-xl font-medium sm:text-2xl md:text-3xl",
      "3xl/semibold": "text-xl font-semibold sm:text-2xl md:text-3xl",
      "3xl/bold": "text-xl font-bold sm:text-2xl md:text-3xl",
      "3xl/extrabold": "text-xl font-extrabold sm:text-2xl md:text-3xl",

      // 4xl
      "4xl/normal": "text-2xl font-normal sm:text-3xl md:text-4xl",
      "4xl/medium": "text-2xl font-medium sm:text-3xl md:text-4xl",
      "4xl/semibold": "text-2xl font-semibold sm:text-3xl md:text-4xl",
      "4xl/bold": "text-2xl font-bold sm:text-3xl md:text-4xl",
      "4xl/extrabold": "text-2xl font-extrabold sm:text-3xl md:text-4xl",

      // 5xl
      "5xl/normal": "text-3xl font-normal sm:text-4xl md:text-5xl",
      "5xl/medium": "text-3xl font-medium sm:text-4xl md:text-5xl",
      "5xl/semibold": "text-3xl font-semibold sm:text-4xl md:text-5xl",
      "5xl/bold": "text-3xl font-bold sm:text-4xl md:text-5xl",
      "5xl/extrabold": "text-3xl font-extrabold sm:text-4xl md:text-5xl",

      // 6xl
      "6xl/normal": "text-4xl font-normal sm:text-5xl md:text-6xl",
      "6xl/medium": "text-4xl font-medium sm:text-5xl md:text-6xl",
      "6xl/semibold": "text-4xl font-semibold sm:text-5xl md:text-6xl",
      "6xl/bold": "text-4xl font-bold sm:text-5xl md:text-6xl",
      "6xl/extrabold": "text-4xl font-extrabold sm:text-5xl md:text-6xl",

      // 7xl
      "7xl/normal": "text-5xl font-normal sm:text-6xl md:text-7xl",
      "7xl/medium": "text-5xl font-medium sm:text-6xl md:text-7xl",
      "7xl/semibold": "text-5xl font-semibold sm:text-6xl md:text-7xl",
      "7xl/bold": "text-5xl font-bold sm:text-6xl md:text-7xl",
      "7xl/extrabold": "text-5xl font-extrabold sm:text-6xl md:text-7xl",
    },
  },
  defaultVariants: {
    variant: "md/normal",
  },
});

function Typography({
  as = "p",
  variant = "base/normal",
  className,
  ...props
}: TypographyProps) {
  const Comp = as;

  return (
    <Comp
      className={cn("text-balance", typographyVariants({ variant }), className)}
      {...props}
    />
  );
}

export { Typography, type TypographyProps, typographyVariants };

"use client";

import * as CheckboxPrimitive from "@radix-ui/react-checkbox";
import { Check } from "lucide-react";
import * as React from "react";

import { cn } from "@/lib/utils";

const Checkbox = React.forwardRef<
  React.ElementRef<typeof CheckboxPrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof CheckboxPrimitive.Root>
>(({ className, ...props }, ref) => (
  <CheckboxPrimitive.Root
    ref={ref}
    className={cn(
      "peer h-5 w-5 shrink-0 rounded-cb-md border border-foreground ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cb-ring focus-visible:ring-offset-1 disabled:cursor-not-allowed disabled:opacity-50 data-[state=checked]:bg-foreground data-[state=checked]:text-background",
      className
    )}
    {...props}
  >
    <CheckboxPrimitive.Indicator
      className={cn("flex items-center justify-center text-current")}
    >
      <Check className="h-4 w-4" />
    </CheckboxPrimitive.Indicator>
  </CheckboxPrimitive.Root>
));
Checkbox.displayName = CheckboxPrimitive.Root.displayName;

export { Checkbox };
